   handler therefore reported a fully-saved change as a 500, and an admin told "failed" about a
   write that landed has no correct next move ΓÇö retrying re-applies it, assuming nothing saved is
   simply wrong. Not hypothetical: `changelog.id` being handed a `log-ΓÇª` text id instead of a uuid
   made *every* Content Admin mutation fail exactly this way. So the error goes to the server log,
   where it stays findable, and the response keeps its normal success shape with a `warning` added.
   Returns `undefined` when the entry was written. */
async function audit(entry: Omit<ChangeLogEntry, 'Id' | 'At'>): Promise<string | undefined> {
  try {
    await appendChangeLog(entry);
  } catch (err) {
    console.error(`appendChangeLog failed after a committed library write (${entry.Action} ${entry.Collection}/${entry.ObjectId}):`, err);
    return 'The change was saved, but its audit-log entry could not be written.';
  }
  return undefined;
}

/** Sends a route's normal success body, plus `warning` when the audit append failed. With no
 *  warning this is byte-for-byte what the route always sent ΓÇö the field is absent, not null. */
function succeed(res: Response, body: object, warning?: string) {
  res.json(warning === undefined ? body : { ...body, warning });
}

export const libraryRouter = Router();

libraryRouter.use(requireAuth);

libraryRouter.get('/', wrap(async (_req, res) => {
  res.json({ library: await getLibrary() });
}));

libraryRouter.get('/validation', requireAdmin, wrap(async (_req, res) => {
  res.json({ issues: validateLibrary(await getLibrary()) });
}));

libraryRouter.get('/changelog', requireAdmin, wrap(async (_req, res) => {
  const log = await listChangeLog();
  res.json({
    entries: log.map((e) => ({ ...e, Diffs: diffEntry(e.Before, e.After) })),
  });
}));

