/* Every write route here does two non-transactional things in sequence: `saveLibrary()`, then
   `appendChangeLog()`. The save commits first, so a throwing append used to reject out of the
   handler and come back as a 500 ΓÇö telling the admin a write failed that had already landed,
   which leaves no correct next move (retrying re-applies it; assuming nothing saved is wrong).
   This has bitten for real: repo.ts's changelog id bug made *every* Content Admin mutation fail
   at its audit step while the write succeeded. These pin the replacement ΓÇö the write still
   happens, the response still reports its normal success shape and status, and the audit failure
   rides along as a `warning` while the underlying error still reaches the server log. */
describe('a failed audit-log append is a warning, not a failed request', () => {
  const deleteEntry = {
    Id: 'cl-1',
    At: '2026-09-11T18:00:00.000Z',
    Who: 'Mike',
    Action: 'delete' as const,
    Collection: 'virtues',
    ObjectId: 'v-resolve',
    ObjectName: 'Resolve',
    Before: { Id: 'v-resolve', Name: 'Resolve', Tagline: 'Grit & Will' },
    After: null,
  };

  // label, the call, and the part of the normal success body that must still be intact ΓÇö the
  // warning replaces nothing the client already reads.
  const writeRoutes: [string, () => Promise<TestResponse>, (res: TestResponse) => void][] = [
    ['create', () => request(appAs(true)).post('/library/virtues').send({ Name: 'Resolve' }),
      (res) => { expect(res.body.object.Name).toBe('Resolve'); expect(res.body.object.Id).toMatch(/^v-/); }],
    ['update', () => request(appAs(true)).put('/library/virtues/v-might').send({ Tagline: 'Force' }),
      (res) => expect(res.body.object).toMatchObject({ Id: 'v-might', Name: 'Might', Tagline: 'Force' })],
    ['delete', () => request(appAs(true)).delete('/library/virtues/v-might'),
